_ubb_jq_body_record_billed_search() {
  jq --compact-output --null-input \
    --arg p_customer_id "$_ubb_p_customer_id" \
    --arg p_idempotency_key "$_ubb_p_idempotency_key" \
    --arg p_task_id "$_ubb_p_task_id" \
    --from-file /dev/stdin <<'UBB_JQ'
  {
    "customer_id": $p_customer_id,
    "idempotency_key": $p_idempotency_key,
    "task_id": $p_task_id,
    # event_type = "billed.search" · event_type "billed.search"
    # event_type.costing_method = "reported" · event_type "billed.search"
    # event_type.source_shape_id = "google.gemini.rest.v1" · event_type "billed.search"
    # event_type.response_shape_representation = "json" · event_type "billed.search"
    "event_type": "billed.search",
    # provider = "google" · provider "google"
    "provider": "google"
  }
UBB_JQ
}

# A stop is returned as UBB_EXIT_STOP_REQUESTED, with the event recorded.
# Return it from your own code unchanged, up to whatever runs the work.
# This file never calls your supplier. Pass the path of a file holding
# the response it returned, as JSON. One that does not hold what a
# declared path reads is refused as UBB_EXIT_VALUE_REFUSED: nothing is
# sent, and a missing quantity is never recorded as none.
ubb_record_billed_search() {
  UBB_STOP_REQUESTED=
  _ubb_preflight || return $?
  _ubb_environment || return $?
  _ubb_p_customer_id=
  _ubb_p_idempotency_key=
  _ubb_p_task_id=
  _ubb_p_response=
  for _ubb_argument in "$@"; do
    case $_ubb_argument in
      customer_id=*) _ubb_p_customer_id=${_ubb_argument#customer_id=} ;;
      idempotency_key=*) _ubb_p_idempotency_key=${_ubb_argument#idempotency_key=} ;;
      task_id=*) _ubb_p_task_id=${_ubb_argument#task_id=} ;;
      response=*) _ubb_p_response=${_ubb_argument#response=} ;;
      *)
        _ubb_unknown ubb_record_billed_search "$_ubb_argument"
        return "$UBB_EXIT_USAGE"
        ;;
    esac
  done
  [ -n "$_ubb_p_customer_id" ] || {
    _ubb_missing ubb_record_billed_search customer_id
    return "$UBB_EXIT_USAGE"
  }
  [ -n "$_ubb_p_idempotency_key" ] || {
    _ubb_missing ubb_record_billed_search idempotency_key
    return "$UBB_EXIT_USAGE"
  }
  [ -n "$_ubb_p_task_id" ] || {
    _ubb_missing ubb_record_billed_search task_id
    return "$UBB_EXIT_USAGE"
  }
  [ -n "$_ubb_p_response" ] || {
    _ubb_missing ubb_record_billed_search response
    return "$UBB_EXIT_USAGE"
  }
  # provider_response_cost_micros.source_path = ["billing","amountMinor"] · event_type "billed.search"
  # provider_response_cost_micros.amount_representation = "minor_units" · event_type "billed.search"
  _ubb_read=$(_ubb_jq_cost_record_billed_search "$_ubb_p_response") || return "$UBB_EXIT_VALUE_REFUSED"
  _ubb_read_amount ubb_record_billed_search provider_response_cost_micros '["billing","amountMinor"]' || return $?
  # currency.source_path = ["billing","currency"] · event_type "billed.search"
  _ubb_read=$(_ubb_jq_currency_record_billed_search "$_ubb_p_response") || return "$UBB_EXIT_VALUE_REFUSED"
  _ubb_read_currency ubb_record_billed_search currency '["billing","currency"]' || return $?
  _ubb_pin_currency '' "$_ubb_reported" || return $?
  _ubb_pinned_currency=$_ubb_currency
  _ubb_to_micros "$_ubb_amount" 'minor_units' "$_ubb_currency" || return $?
  _ubb_micros_provider_response_cost_micros=$_ubb_micros
  _ubb_body=$(_ubb_jq_body_record_billed_search) || return "$UBB_EXIT_VALUE_REFUSED"
  _ubb_body="{\"provider_response_cost_micros\":$_ubb_micros_provider_response_cost_micros,${_ubb_body#?}"
  _ubb_body="{\"currency\":\"$_ubb_pinned_currency\",${_ubb_body#?}"
  _ubb_post '/api/v1/metering/usage' "$_ubb_body" || return $?
  _ubb_acknowledge "$_ubb_p_idempotency_key"
}

_ubb_jq_body_close_task() {
  jq --compact-output --null-input \
    --arg p_outcome "$_ubb_p_outcome" \
    --arg p_outcome_reason "$_ubb_p_outcome_reason" \
    --arg p_reason_detail "$_ubb_p_reason_detail" \
    --from-file /dev/stdin <<'UBB_JQ'
  {
    "outcome": $p_outcome
  }
  + (if $p_outcome_reason == "" then {} else {"outcome_reason": $p_outcome_reason} end)
  + (if $p_reason_detail == "" then {} else {"reason_detail": $p_reason_detail} end)
UBB_JQ
}

# outcome is delivered, failed or cancelled, and UBB never guesses it. A
# failure also says why: pass outcome_reason, and reason_detail if you
# have a sentence to go with it.
ubb_close_task() {
  _ubb_preflight || return $?
  _ubb_environment || return $?
  _ubb_p_task_id=
  _ubb_p_outcome=
  _ubb_p_outcome_reason=
  _ubb_p_reason_detail=
  for _ubb_argument in "$@"; do
    case $_ubb_argument in
      task_id=*) _ubb_p_task_id=${_ubb_argument#task_id=} ;;
      outcome=*) _ubb_p_outcome=${_ubb_argument#outcome=} ;;
      outcome_reason=*) _ubb_p_outcome_reason=${_ubb_argument#outcome_reason=} ;;
      reason_detail=*) _ubb_p_reason_detail=${_ubb_argument#reason_detail=} ;;
      *)
        _ubb_unknown ubb_close_task "$_ubb_argument"
        return "$UBB_EXIT_USAGE"
        ;;
    esac
  done
  [ -n "$_ubb_p_task_id" ] || {
    _ubb_missing ubb_close_task task_id
    return "$UBB_EXIT_USAGE"
  }
  [ -n "$_ubb_p_outcome" ] || {
    _ubb_missing ubb_close_task outcome
    return "$UBB_EXIT_USAGE"
  }
  _ubb_url_value ubb_close_task task_id "$_ubb_p_task_id" || return $?
  _ubb_body=$(_ubb_jq_body_close_task) || return "$UBB_EXIT_VALUE_REFUSED"
  _ubb_post '/api/v1/tasks/'"$_ubb_p_task_id"'/close' "$_ubb_body" || return $?
  _ubb_closed="$_ubb_closed $_ubb_p_task_id"
}
